class Solution {
    public:bool canBeValid(string s,string locked){
        if(s.size()&1)return false;
        int low=0,high=0;
        for(int i=0;i<(int)s.size();++i){
            if(locked[i]=='0'){
                --low;
                ++high;
            }else if(s[i]=='('){
                ++low;
                ++high;
            }else{
                --low;
                --high;
            }
            if(high<0)return false;
            low=max(low,0);
        }
        return low==0;
    }
};
